'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const request = require('supertest');

const app = require('../server');

test('GET /status returns ok, uptime_ms and ISO now', async () => {
  const res = await request(app).get('/status');

  assert.equal(res.status, 200);
  const body = res.body;
  assert.equal(body.ok, true);
  assert.equal(Number.isInteger(body.uptime_ms), true);
  assert.ok(body.uptime_ms >= 0);

  // "now" must parse as a valid date and round-trip to the same string
  const now = new Date(body.now);
  assert.equal(Number.isNaN(now.getTime()), false);
  assert.equal(now.toISOString(), body.now);

  // uptime should be <= time since module load (small tolerance)
  assert.ok(body.uptime_ms < 60_000);
});

test('non-GET methods on /status are rejected with 405 and Allow header', async () => {
  for (const method of ['post', 'put', 'patch', 'delete']) {
    const res = await request(app)[method]('/status');
    assert.equal(res.status, 405, `${method.toUpperCase()} should be 405`);
    assert.equal(res.headers.allow, 'GET');
  }

  const opts = await request(app).options('/status');
  assert.equal(opts.status, 405);
  assert.equal(opts.headers.allow, 'GET');

  const head = await request(app).head('/status');
  assert.equal(head.status, 405);
  assert.equal(head.headers.allow, 'GET');
});

test('unknown routes still return 404', async () => {
  const res = await request(app).get('/nope');
  assert.equal(res.status, 404);
});

